//! The concrete 3D / `f32` geometry, shape, and collider `#[pyclass]` types,
//! plus the `register_geometry` function used by `#[pymodule]`.
//!
//! This module used to be generated by a `(Real, DIM)`-parameterized macro so
//! that several cdylibs could each expand their own concrete types. There is
//! now a single concrete target — 3D, `f32` — so the types are written out
//! directly, with no macros.

use crate::*;
use rapier3d as rapier;

use crate::numpy::{PyArray2, PyReadonlyArray2};
use crate::pyo3::exceptions::{PyIndexError, PyTypeError, PyValueError};
use crate::pyo3::prelude::*;
use crate::pyo3::pyclass::CompareOp;

/// Read the rows of an `(M, N)` integer ndarray of element type `T`, or `None` if `obj` is
/// not such an array. Any memory layout is accepted.
fn int_ndarray_rows<T, const N: usize>(obj: &Bound<'_, PyAny>) -> Option<PyResult<Vec<[u32; N]>>>
where
    T: crate::numpy::Element + Copy + TryInto<u32> + std::fmt::Display,
{
    let arr = obj.extract::<PyReadonlyArray2<T>>().ok()?;
    let view = arr.as_array();
    if view.ncols() != N {
        return Some(Err(PyValueError::new_err(format!(
            "expected ndarray with shape (M, {N}); got (M, {})",
            view.ncols()
        ))));
    }
    let rows = view
        .rows()
        .into_iter()
        .map(|row| {
            let mut out = [0u32; N];
            for (o, x) in out.iter_mut().zip(row.iter()) {
                *o = (*x)
                    .try_into()
                    .map_err(|_| PyValueError::new_err(format!("invalid index {x}")))?;
            }
            Ok(out)
        })
        .collect();
    Some(rows)
}

/// Read a 1D integer ndarray of element type `T`, or `None` if `obj` is not such an array.
/// Any memory layout is accepted.
fn int_ndarray_1d<T>(obj: &Bound<'_, PyAny>) -> Option<PyResult<Vec<u32>>>
where
    T: crate::numpy::Element + Copy + TryInto<u32> + std::fmt::Display,
{
    let arr = obj.extract::<crate::numpy::PyReadonlyArray1<T>>().ok()?;
    let values = arr
        .as_array()
        .iter()
        .map(|x| {
            (*x).try_into()
                .map_err(|_| PyValueError::new_err(format!("invalid index {x}")))
        })
        .collect();
    Some(values)
}

/// Extract a flat index list: a 1D ndarray of any integer dtype, or a sequence of ints.
pub(crate) fn extract_index_list(obj: &Bound<'_, PyAny>) -> PyResult<Vec<u32>> {
    if let Some(r) = int_ndarray_1d::<u32>(obj)
        .or_else(|| int_ndarray_1d::<i64>(obj))
        .or_else(|| int_ndarray_1d::<i32>(obj))
        .or_else(|| int_ndarray_1d::<u64>(obj))
        .or_else(|| int_ndarray_1d::<u16>(obj))
    {
        return r;
    }
    obj.extract::<Vec<u32>>()
        .map_err(|_| PyTypeError::new_err("expected a 1D integer ndarray or a sequence of ints"))
}

/// Extract an `(M, N)` index matrix: an integer ndarray of any integer dtype, or a sequence of
/// length-`N` sequences (lists or tuples).
pub(crate) fn extract_index_rows<const N: usize>(
    obj: &Bound<'_, PyAny>,
) -> PyResult<Vec<[u32; N]>> {
    if let Some(r) = int_ndarray_rows::<u32, N>(obj)
        .or_else(|| int_ndarray_rows::<i64, N>(obj))
        .or_else(|| int_ndarray_rows::<i32, N>(obj))
        .or_else(|| int_ndarray_rows::<u64, N>(obj))
        .or_else(|| int_ndarray_rows::<u16, N>(obj))
    {
        return r;
    }
    let seq: Vec<Vec<u32>> = obj.extract()?;
    seq.iter()
        .map(|c| {
            <[u32; N]>::try_from(c.as_slice()).map_err(|_| {
                PyValueError::new_err(format!(
                    "expected inner sequence of length {N}; got {}",
                    c.len(),
                ))
            })
        })
        .collect()
}

/// Extract an `Mx3` index matrix → `Vec<[u32; 3]>` (integer ndarray or nested sequences).
pub fn extract_indices(obj: &Bound<'_, PyAny>) -> PyResult<Vec<[u32; 3]>> {
    extract_index_rows::<3>(obj)
}

/// Extract an `Mx2` index matrix → `Vec<[u32; 2]>` (integer ndarray or nested sequences).
pub fn extract_indices_2(obj: &Bound<'_, PyAny>) -> PyResult<Vec<[u32; 2]>> {
    extract_index_rows::<2>(obj)
}

/// Reject the index buffers referencing vertices out of `0..num_vertices`.
fn check_indices_in_bounds<const N: usize>(
    indices: &[[u32; N]],
    num_vertices: usize,
) -> PyResult<()> {
    match indices
        .iter()
        .flatten()
        .find(|i| **i as usize >= num_vertices)
    {
        Some(i) => Err(PyValueError::new_err(format!(
            "vertex index {i} out of bounds for {num_vertices} vertices"
        ))),
        None => Ok(()),
    }
}

/// Reject the voxel sizes the voxelizer cannot handle.
fn check_voxel_size(voxel_size: Real) -> PyResult<()> {
    if voxel_size > 0.0 && voxel_size.is_finite() {
        Ok(())
    } else {
        Err(PyValueError::new_err(format!(
            "voxel_size must be positive and finite; got {voxel_size}"
        )))
    }
}

/// Extract a 3D heightfield's `(nrows, ncols)` height grid: a `float32`/`float64` ndarray of
/// any memory layout, or nested sequences.
///
/// `heights[i, j]` is the height at row `i` (along Z) and column `j` (along X), converted to
/// parry's column-major storage.
fn extract_heights(obj: &Bound<'_, PyAny>) -> PyResult<rapier::parry::utils::Array2<Real>> {
    fn from_view<T: Copy + Into<f64>>(
        view: crate::numpy::ndarray::ArrayView2<'_, T>,
    ) -> rapier::parry::utils::Array2<Real> {
        let (nrows, ncols) = view.dim();
        rapier::parry::utils::Array2::from_fn(nrows, ncols, |i, j| view[[i, j]].into() as Real)
    }
    let heights = if let Ok(arr) = obj.extract::<PyReadonlyArray2<f32>>() {
        from_view(arr.as_array())
    } else if let Ok(arr) = obj.extract::<PyReadonlyArray2<f64>>() {
        from_view(arr.as_array())
    } else {
        let rows: Vec<Vec<Real>> = obj.extract()?;
        let ncols = rows.first().map_or(0, |r| r.len());
        if rows.iter().any(|r| r.len() != ncols) {
            return Err(PyValueError::new_err(
                "heights rows must all have the same length",
            ));
        }
        rapier::parry::utils::Array2::from_fn(rows.len(), ncols, |i, j| rows[i][j])
    };
    if heights.nrows() < 2 || heights.ncols() < 2 {
        return Err(PyValueError::new_err(format!(
            "heights must have at least 2 rows and 2 columns; got ({}, {})",
            heights.nrows(),
            heights.ncols()
        )));
    }
    Ok(heights)
}

// ============================================================
// ColliderHandle (moved from dynamics)
// ============================================================

/// Opaque, generational handle identifying a collider in a `ColliderSet`.
///
/// Handles remain valid until the collider is removed. After removal,
/// the slot may be reused with a bumped generation, so old handles
/// pointing to a freed slot compare unequal to the new one. Cheap to
/// copy and hash.
#[pyclass(name = "ColliderHandle", module = "rapier", frozen)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct ColliderHandle(pub rapier::geometry::ColliderHandle);

#[pymethods]
impl ColliderHandle {
    /// Construct a handle from raw `(index, generation)` parts.
    ///
    /// Mostly useful for tests and serialization round-trips; in
    /// normal use, handles come from `ColliderSet.insert(...)`.
    #[new]
    #[pyo3(signature = (index=0, generation=0))]
    fn new(index: u32, generation: u32) -> Self {
        Self(rapier::geometry::ColliderHandle::from_raw_parts(
            index, generation,
        ))
    }
    /// Build a handle from raw `(index, generation)` parts.
    #[staticmethod]
    fn from_raw_parts(index: u32, generation: u32) -> Self {
        Self(rapier::geometry::ColliderHandle::from_raw_parts(
            index, generation,
        ))
    }
    /// Return the sentinel "invalid" handle.
    ///
    /// Never refers to a real collider; useful as a default value.
    #[staticmethod]
    fn invalid() -> Self {
        Self(rapier::geometry::ColliderSet::invalid_handle())
    }
    /// Slot index inside the underlying `ColliderSet`.
    #[getter]
    fn index(&self) -> u32 {
        self.0.into_raw_parts().0
    }
    /// Generation counter for the slot. Bumped on each reuse.
    #[getter]
    fn generation(&self) -> u32 {
        self.0.into_raw_parts().1
    }
    fn __hash__(&self) -> u64 {
        let (i, g) = self.0.into_raw_parts();
        ((i as u64) << 32) | (g as u64)
    }
    fn __richcmp__(&self, other: &Self, op: CompareOp) -> PyResult<bool> {
        match op {
            CompareOp::Eq => Ok(self.0 == other.0),
            CompareOp::Ne => Ok(self.0 != other.0),
            _ => Err(PyTypeError::new_err(
                "ColliderHandle supports only == and !=",
            )),
        }
    }
    fn __repr__(&self) -> String {
        let (i, g) = self.0.into_raw_parts();
        format!("ColliderHandle(index={}, generation={})", i, g)
    }
}

// ============================================================
// ShapeType (enum)
// ============================================================

/// Discriminant returned by `SharedShape.shape_type`.
///
/// Use this to decide which `as_*()` downcast accessor to call on a
/// `SharedShape`. `CUSTOM` covers user-defined shapes that do not
/// match any built-in variant.
#[pyclass(name = "ShapeType", module = "rapier", eq, eq_int, hash, frozen)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ShapeType {
    BALL,
    CUBOID,
    CAPSULE,
    SEGMENT,
    TRIANGLE,
    VOXELS,
    TRIMESH,
    POLYLINE,
    HALFSPACE,
    HEIGHTFIELD,
    COMPOUND,
    CONVEX_POLYGON,
    CONVEX_POLYHEDRON,
    CYLINDER,
    CONE,
    ROUND_CUBOID,
    ROUND_TRIANGLE,
    ROUND_CYLINDER,
    ROUND_CONE,
    ROUND_CONVEX_POLYHEDRON,
    ROUND_CONVEX_POLYGON,
    CUSTOM,
}

impl ShapeType {
    pub(crate) fn from_rapier(t: rapier::parry::shape::ShapeType) -> Self {
        // The dim-specific variants are gated by parry's `dim2`/`dim3`
        // features, but the cdylib already knows its own dim, so we
        // express the mapping using the dim-specific helper macro.
        {
            use rapier::parry::shape::ShapeType as PT;
            match t {
                PT::Ball => ShapeType::BALL,
                PT::Cuboid => ShapeType::CUBOID,
                PT::Capsule => ShapeType::CAPSULE,
                PT::Segment => ShapeType::SEGMENT,
                PT::Triangle => ShapeType::TRIANGLE,
                PT::Voxels => ShapeType::VOXELS,
                PT::TriMesh => ShapeType::TRIMESH,
                PT::Polyline => ShapeType::POLYLINE,
                PT::HalfSpace => ShapeType::HALFSPACE,
                PT::HeightField => ShapeType::HEIGHTFIELD,
                PT::Compound => ShapeType::COMPOUND,
                PT::ConvexPolyhedron => ShapeType::CONVEX_POLYHEDRON,
                PT::Cylinder => ShapeType::CYLINDER,
                PT::Cone => ShapeType::CONE,
                PT::RoundCuboid => ShapeType::ROUND_CUBOID,
                PT::RoundTriangle => ShapeType::ROUND_TRIANGLE,
                PT::RoundCylinder => ShapeType::ROUND_CYLINDER,
                PT::RoundCone => ShapeType::ROUND_CONE,
                PT::RoundConvexPolyhedron => ShapeType::ROUND_CONVEX_POLYHEDRON,
                _ => ShapeType::CUSTOM,
            }
        }
    }
}

// ============================================================
// ColliderType
// ============================================================

/// Distinguishes a `SOLID` collider from a `SENSOR`.
///
/// Solid colliders generate contact forces; sensor colliders only
/// fire intersection events and do not produce contact responses.
#[pyclass(name = "ColliderType", module = "rapier", eq, eq_int, hash, frozen)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ColliderType {
    SOLID,
    SENSOR,
}

impl ColliderType {
    #[allow(dead_code)]
    pub(crate) fn to_rapier(self) -> rapier::geometry::ColliderType {
        match self {
            Self::SOLID => rapier::geometry::ColliderType::Solid,
            Self::SENSOR => rapier::geometry::ColliderType::Sensor,
        }
    }
    #[allow(dead_code)]
    pub(crate) fn from_rapier(t: rapier::geometry::ColliderType) -> Self {
        match t {
            rapier::geometry::ColliderType::Solid => Self::SOLID,
            rapier::geometry::ColliderType::Sensor => Self::SENSOR,
        }
    }
}

// ============================================================
// ColliderEnabled
// ============================================================

/// Enabled-state of a collider.
///
/// `DISABLED_BY_PARENT` means the parent rigid-body is disabled, so
/// the collider is effectively off without being explicitly disabled
/// by the user.
#[pyclass(name = "ColliderEnabled", module = "rapier", eq, eq_int, hash, frozen)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ColliderEnabled {
    ENABLED,
    DISABLED_BY_PARENT,
    DISABLED,
}

impl ColliderEnabled {
    #[allow(dead_code)]
    pub(crate) fn from_rapier(t: rapier::geometry::ColliderEnabled) -> Self {
        match t {
            rapier::geometry::ColliderEnabled::Enabled => Self::ENABLED,
            rapier::geometry::ColliderEnabled::DisabledByParent => Self::DISABLED_BY_PARENT,
            rapier::geometry::ColliderEnabled::Disabled => Self::DISABLED,
        }
    }
}

// ============================================================
// ActiveEvents (bitflags)
// ============================================================

/// Per-collider opt-in flags selecting which events to emit.
///
/// A collider only emits an event kind if it has the corresponding
/// flag set. Use `COLLISION_EVENTS` to receive `CollisionEvent`
/// (started/stopped) and `CONTACT_FORCE_EVENTS` to receive
/// `ContactForceEvent`. Combine flags via `|`.
#[pyclass(name = "ActiveEvents", module = "rapier", frozen)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ActiveEvents(pub rapier::pipeline::ActiveEvents);

#[pymethods]
impl ActiveEvents {
    /// Construct from a raw bit pattern. Unknown bits are dropped.
    #[new]
    #[pyo3(signature = (bits = 0))]
    fn new(bits: u32) -> Self {
        Self(rapier::pipeline::ActiveEvents::from_bits_truncate(bits))
    }
    /// Return the empty flag set (no events).
    #[staticmethod]
    fn empty() -> Self {
        Self(rapier::pipeline::ActiveEvents::empty())
    }
    /// Return the flag set with every known event kind enabled.
    #[staticmethod]
    fn all_events() -> Self {
        Self(rapier::pipeline::ActiveEvents::all())
    }
    #[classattr]
    const COLLISION_EVENTS: ActiveEvents =
        ActiveEvents(rapier::pipeline::ActiveEvents::COLLISION_EVENTS);
    #[classattr]
    const CONTACT_FORCE_EVENTS: ActiveEvents =
        ActiveEvents(rapier::pipeline::ActiveEvents::CONTACT_FORCE_EVENTS);
    #[classattr]
    const NONE: ActiveEvents = ActiveEvents(rapier::pipeline::ActiveEvents::empty());

    /// Raw bit pattern of the flag set.
    #[getter]
    fn bits(&self) -> u32 {
        self.0.bits()
    }
    /// True iff all flags in `other` are also set on `self`.
    fn contains(&self, other: &Self) -> bool {
        self.0.contains(other.0)
    }
    /// True iff no flags are set.
    fn is_empty(&self) -> bool {
        self.0.is_empty()
    }
    fn __contains__(&self, other: &Self) -> bool {
        self.0.contains(other.0)
    }
    fn __or__(&self, other: &Self) -> Self {
        Self(self.0 | other.0)
    }
    fn __and__(&self, other: &Self) -> Self {
        Self(self.0 & other.0)
    }
    fn __xor__(&self, other: &Self) -> Self {
        Self(self.0 ^ other.0)
    }
    fn __invert__(&self) -> Self {
        Self(!self.0)
    }
    fn __sub__(&self, other: &Self) -> Self {
        Self(self.0 - other.0)
    }
    fn __bool__(&self) -> bool {
        !self.0.is_empty()
    }
    fn __richcmp__(&self, other: &Self, op: CompareOp) -> PyResult<bool> {
        match op {
            CompareOp::Eq => Ok(self.0 == other.0),
            CompareOp::Ne => Ok(self.0 != other.0),
            _ => Err(PyTypeError::new_err("ActiveEvents supports only == and !=")),
        }
    }
    fn __hash__(&self) -> u64 {
        self.0.bits() as u64
    }
    fn __repr__(&self) -> String {
        format!("ActiveEvents(bits={:#010b})", self.0.bits())
    }
}

