        ActiveCollisionTypes(rapier::geometry::ActiveCollisionTypes::FIXED_FIXED);
    #[classattr]
    const NONE: ActiveCollisionTypes =
        ActiveCollisionTypes(rapier::geometry::ActiveCollisionTypes::empty());

    /// Raw bit pattern of the flag set.
    #[getter]
